import json,re,html
from pathlib import Path
root=Path('/Users/alexandremasmejean/.codex/.chatgpt-projects/g-p-6ad59c015c308191aa21cba63c71a6dc/sites/liberer-la-retraite/dist/corpus')
checks={'impots':['1394','206'],'impots-annexe-3':['344-0 A'],'impots-annexe-2':['286 L']}
for name,ns in checks.items():
 data=json.loads((root/(name+'.json')).read_text())
 for n in ns:
  a=next((a for a in data if a['number']==n),None)
  if not a:
   print(name,n,'ABSENT');continue
  print('\\nRENVOI',name,n,a['source_id'])
  ps=re.findall(r'<p["'^>]*>(.*?)</p>'"',a['source_xml'],re.S)
  if n=='1394':
   for p in ps:
    if re.match(r'\\s*2°',html.unescape(re.sub('<["'^>]+>'"','',p))):print(p)
  elif n=='206':
   start=next((i for i,p in enumerate(ps) if re.match(r'\\s*5\\.',html.unescape(re.sub('<["'^>]+>'"','',p)))),None)
   end=next((i for i,p in enumerate(ps) if start is not None and i>start and re.match(r'\\s*6\\.',html.unescape(re.sub('<["'^>]+>'"','',p)))),len(ps))
   if start is not None: print('\\n'.join(ps[start:end]))
  else:
   print(a['source_xml']);print('NOTES:',a['source_notes_xml'])
PY"

